import{z as s,x as A,o as i,c,q as n,j as E,D as e,d as o,s as r,S as d,b as l}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Jacobi 并行解码","description":"","frontmatter":{"title":"Jacobi 并行解码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/jacobi-decoding.md","filePath":"llm/jacobi-decoding.md","lastUpdated":1791413859000}'),B={name:"llm/jacobi-decoding.md"};function p(m,a,h,b,D,g){const t=A("Mermaid");return i(),c("div",null,[a[2]||(a[2]=n('<h1 id="jacobi-并行解码" tabindex="-1">Jacobi 并行解码 <a class="header-anchor" href="#jacobi-并行解码" aria-label="Permalink to &quot;Jacobi 并行解码&quot;">​</a></h1><div class="epigraph"><p>把未来 token 看成非线性方程组的未知数，用上一轮猜测并行更新所有位置；对得上的前缀留下，对不上的退回逐步。</p><footer>—— Santilli et al., Accelerating Transformer Inference for Translation via Parallel Decoding, ACL 2023；Lookahead 见 Fu et al., 2024</footer></div><p><a href="/llm/self-speculative-decoding">上一课</a>仍保留串行草稿：浅层逐步猜，\\(\\gamma\\) 步之后才校验。本课把「猜」也并行化。Santilli 等人把翻译解码写成 Jacobi / Gauss–Seidel 迭代：一次前向同时更新多个未来位置，用上一轮的填法当条件。它不保证每轮都前进很多；精确性来自 <em>验证与回退</em>，不是来自一次 Jacobi 扫就把方程解完。主干已有 <a href="/llm/lookahead-decoding">Lookahead Decoding</a> 把 n-gram 池加上去；本课只补方程视角与朴素 Jacobi 为什么常常不加速，以免后课把 Lookahead 当成唯一的并行解码。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自回归 \\(x_{t+1}=f(x_{\\le t})\\) 是三角依赖。GPU 能一次算很多位置，因果却强迫逐步。投机用外源填未来位置；自投机用浅层填。有没有第三种填法：用 <em>同一完整模型、上一轮的猜测</em> 填？这就是定点迭代。缺口是期望前进：若初始猜测远离真解，一轮并行更新之后，只有最左边一个位置可能对，其余全废，还多付了宽查询的注意力。翻译上，Santilli 等人观察到在某些设置可减少前向次数；开放生成上，无辅助结构的 Jacobi 经常亏。Lookahead 要解决的正是「猜出来的碎片如何缓存再验」，本课先把不加池的 Jacobi 写清楚。</p><p><span class="marginnote">Jacobi 解码可以做成与贪心路径一致：每轮只提交从左起连续猜对的前缀。采样版本需要对每个位置定义接受规则，否则分布漂到迭代器上。不要宣传「并行所以无损」而不写提交规则。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>初始化未来窗口 \\(\\tilde x_{t+1:t+W}\\)（随机、复制上一 token、或抄提示 n-gram）。每轮用完整模型对窗口做一次前向（因果掩码仍以 <em>已提交前缀 + 当前猜测</em> 为条件），得到各位置新的 argmax 或样本，写回窗口。从左扫描：与校验分布一致的最长前缀提交，窗口右移。Gauss–Seidel 变体在同一前向里用刚刚更新的左侧位置条件右侧，依赖核能否提供这种掩码；标准因果核通常做的是 Jacobi（整窗看上一轮）。</p><p>窗口 \\(W\\) 越大，一次 <a href="/llm/flashattention">FlashAttention</a> 的查询越长，算术强度上升，这是相对逐步 decode 的真正硬件理由。但未提交的位置是错条件，算力打在可能被丢的查询上。Lookahead 把窗口轨迹切成 n-gram 进池，验证枝单独掩码，才把「打在错条件上的计算」变成可回收的提案。</p><p><span class="marginnote">数字实例：取 \\(W=8\\)。一轮前向要为 8 个猜测位置各付一份查询计算；若从左扫描只有第 1 个位置与目标 argmax 一致，这轮就只提交 1 个 token，其余 7 份算力随窗口右移作废——这就是「期望提交 \\(\\approx 1\\)」最直观的代价账。</span></p>',10)),(i(),E(d,null,{default:e(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%AA%97%E5%8F%A3%E7%8C%9C%E6%B5%8B%20x%CC%83%22%5D%20--%3E%20F%5B%22%E4%B8%80%E6%AC%A1%E5%B9%B6%E8%A1%8C%E5%89%8D%E5%90%91%22%5D%0A%20%20F%20--%3E%20U%5B%22%E5%B9%B6%E8%A1%8C%E6%9B%B4%E6%96%B0%E6%95%B4%E7%AA%97%22%5D%0A%20%20U%20--%3E%20C%5B%22%E4%BB%8E%E5%B7%A6%E6%8F%90%E4%BA%A4%E4%B8%80%E8%87%B4%E5%89%8D%E7%BC%80%22%5D%0A%20%20C%20--%3E%20W%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[o("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"定点 \\(x=f(x)\\) 的收敛速度取决于 \\(f\\) 对右侧扰动有多敏感。语言模型里，一个早期 token 错误会让后续条件全部错位，收缩系数不小于 1，故朴素 Jacobi 的提交长度期望接近 1。翻译有较强的局部对应，偶尔能多提交几个。开放生成依赖池与验证枝，不是依赖多扫几次窗口。墙钟上，只有「期望提交 \\(\\gt 1\\) 且宽查询仍在带宽墙内」才加速；prefill 已经算力密集时，再加宽窗口会撞计算屋顶。",-1)),(i(),E(d,null,{default:e(()=>[r(t,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E7%AC%AC%20k%20%E8%BD%AE%E7%AA%97%E5%8F%A3%3A%20g1%20g2%20g3%20g4%22%5D%20--%3E%20P%5B%22%E4%B8%80%E6%AC%A1%E5%89%8D%E5%90%91%E7%BB%99%E5%87%BA%E4%BF%AE%E6%AD%A3%20p1..p4%22%5D%0A%20%20P%20--%3E%20S%7B%22%E4%BB%8E%E5%B7%A6%E9%80%90%E4%BD%8D%E6%AF%94%E5%AF%B9%E7%9B%AE%E6%A0%87%22%7D%0A%20%20S%20--%3E%7C%22g1%20%E6%AD%A3%E7%A1%AE%22%7C%20K1%5B%22%E4%BF%9D%E7%95%99%E4%BD%8D%E7%BD%AE%201%22%5D%0A%20%20S%20--%3E%7C%22g2%20%E4%B8%8D%E7%AC%A6%22%7C%20D%5B%22%E4%BD%8D%E7%BD%AE%202%20%E8%B5%B7%E5%85%A8%E9%83%A8%E5%9B%9E%E9%80%80%22%5D%0A%20%20K1%20--%3E%20W2%5B%22%E7%AA%97%E5%8F%A3%E5%8F%B3%E7%A7%BB%201%20%E6%A0%BC%2C%20%E5%B0%BE%E9%83%A8%E8%A1%A5%E6%96%B0%E7%8C%9C%E6%B5%8B%22%5D%0A%20%20D%20--%3E%20W2%0A%20%20W2%20--%3E%20R%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=n('<p><span class="marginnote">术语翻译：定点迭代就是「把猜测代回同一个函数、拿输出当新一轮猜测」反复做，直到输入和输出对得上为止。Jacobi 解码把未来几个 token 当未知数，每轮整窗一起代回；而语言模型对早期 token 的错误极其敏感，这个「对得上」往往迟迟不来。</span></p><p>与<a href="/llm/speculative-decoding">投机</a>的差别：投机的草稿分布 \\(q\\) 明确进入似然比；Jacobi 的 \\(q\\) 是上一轮点估计，没有逐步 \\(q(\\tilde x_i)\\) 就不好做 Leviathan residual。实践中贪心 Jacobi 用「是否等于目标 argmax」当接受，采样要另写规则。</p><p><span class="marginnote">常见误区：初学者容易以为「在同一个前向里用刚更新完的左侧位置去条件右侧」还是 Jacobi，实际上那叫 Gauss–Seidel。两者的分界在于整窗看的是上一轮的旧值（Jacobi）还是混入了本轮的新值（Gauss–Seidel）；标准因果注意力核没有为后者准备掩码，写代码前要先确认。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要在生产聊天默认开朴素 Jacobi。有 Lookahead / Medusa / EAGLE 时，Jacobi 只是其中 Lookahead 的生成枝。与分页 KV 的接口：窗口位置的查询仍对应已提交长度之后的逻辑下标，页表要为未提交位置准备临时槽，提交失败则丢槽。投机与 Jacobi 不要无文档地叠两层窗口。</p><p>出处：Santilli et al., ACL 2023；Fu et al., Lookahead Decoding, 2024。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>朴素 Jacobi 用上一轮猜测并行更新未来位置，提交从左连续猜对的前缀。</li><li>开放生成上期望前进常接近 1，加速靠宽查询的强度，不靠魔法收敛。</li><li>Lookahead 在 Jacobi 之上加 n-gram 池与验证枝，才成为可用算法。</li><li>无损必须写提交规则；没有逐步 \\(q\\) 就不能直接套 Leviathan residual。</li><li>宽窗口抬算术强度，也抬可能被丢的 FLOPs。</li><li>后课离开搜索算法，处理流式字符串边界。</li><li>出处：Santilli et al., ACL 2023；Fu et al., 2024。</li></ul>',8))])}const C=s(B,[["render",p]]);export{u as __pageData,C as default};
